export const organizationsJobsActionResponseDescriptionMax = 10000;

export const organizationsJobsActionResponseResponsibilitiesMax = 5000;

export const organizationsJobsActionResponseAddressTextMax = 200;

export const organizationsJobsActionResponsePositionsCountMin = 0;
export const organizationsJobsActionResponsePositionsCountMax = 32767;

export const organizationsJobsActionResponseSalaryMinRegExp = new RegExp(
  "^-?\\d{0,8}(?:\\.\\d{0,2})?$",
);
export const organizationsJobsActionResponseSalaryMaxRegExp = new RegExp(
  "^-?\\d{0,8}(?:\\.\\d{0,2})?$",
);
export const organizationsJobsActionResponseExperienceMinYearsMin = 0;
export const organizationsJobsActionResponseExperienceMinYearsMax = 32767;

export const organizationsJobsActionResponseRequirementsItemMinYearsMin = 0;
export const organizationsJobsActionResponseRequirementsItemMinYearsMax = 32767;

export const organizationsJobsActionResponseRequirementsItemLanguageCodeMax = 3;

export const organizationsJobsActionResponseRequirementsItemCertificationNameMax = 200;

export const organizationsJobsActionResponseRequirementsItemDescriptionMax = 300;

export const OrganizationsJobsActionResponse = zod
  .object({
    id: zod.uuid(),
    title: zod.string().max(organizationsJobsActionResponseTitleMax),
    source_locale: zod.string().max(organizationsJobsActionResponseSourceLocaleMax),
    description: zod.string().max(organizationsJobsActionResponseDescriptionMax),
    responsibilities: zod
      .string()
      .max(organizationsJobsActionResponseResponsibilitiesMax)
      .optional(),
    occupation: zod.uuid().nullish(),
    sector: zod.uuid().nullish(),
    location: zod.uuid().nullish(),
    address_text: zod.string().max(organizationsJobsActionResponseAddressTextMax).optional(),
    work_mode: zod
      .enum(["onsite", "hybrid", "remote"])
      .optional()
      .describe("* `onsite` - Onsite\n* `hybrid` - Hybrid\n* `remote` - Remote"),
    contract_type: zod
      .enum([
        "permanent",
        "fixed_term",
        "temporary",
        "internship",
        "apprenticeship",
        "freelance",
        "seasonal",
      ])
      .describe(
        "* `permanent` - Permanent\n* `fixed_term` - Fixed Term\n* `temporary` - Temporary\n* `internship` - Internship\n* `apprenticeship` - Apprenticeship\n* `freelance` - Freelance\n* `seasonal` - Seasonal",
      ),
    schedule: zod
      .enum(["full_time", "part_time", "shifts"])
      .optional()
      .describe("* `full_time` - Full Time\n* `part_time` - Part Time\n* `shifts` - Shifts"),
    positions_count: zod
      .int()
      .min(organizationsJobsActionResponsePositionsCountMin)
      .max(organizationsJobsActionResponsePositionsCountMax)
      .optional(),
    salary_min: zod
      .stringFormat("decimal", organizationsJobsActionResponseSalaryMinRegExp)
      .nullish(),
    salary_max: zod
      .stringFormat("decimal", organizationsJobsActionResponseSalaryMaxRegExp)
      .nullish(),
    salary_currency: zod.string(),
    salary_period: zod
      .enum(["hour", "day", "month", "year"])
      .optional()
      .describe("* `hour` - Hour\n* `day` - Day\n* `month` - Month\n* `year` - Year"),
    experience_min_years: zod
      .int()
      .min(organizationsJobsActionResponseExperienceMinYearsMin)
      .max(organizationsJobsActionResponseExperienceMinYearsMax)
      .nullish(),
    education_level: zod
      .enum([
        "none",
        "primary",
        "secondary",
        "baccalaureate",
        "vocational",
        "bac_plus_2",
        "bac_plus_3",
        "bac_plus_5",
        "doctorate",
      ])
      .optional()
      .describe(
        "* `none` - None\n* `primary` - Primary\n* `secondary` - Secondary\n* `baccalaureate` - Baccalaureate\n* `vocational` - Vocational\n* `bac_plus_2` - Bac Plus 2\n* `bac_plus_3` - Bac Plus 3\n* `bac_plus_5` - Bac Plus 5\n* `doctorate` - Doctorate",
      ),
    expires_at: zod.iso.datetime({ offset: true }).nullish(),
    requirements: zod
      .array(
        zod
          .object({
            id: zod.uuid(),
            kind: zod
              .enum([
                "skill",
                "occupation_experience",
                "language",
                "education",
                "certification",
                "license",
              ])
              .describe(
                "* `skill` - Skill\n* `occupation_experience` - Occupation Experience\n* `language` - Language\n* `education` - Education\n* `certification` - Certification\n* `license` - License",
              ),
            is_mandatory: zod.boolean().optional(),
            is_legal_requirement: zod.boolean().optional(),
            skill: zod.uuid().nullish(),
            skill_level: zod
              .enum(["unspecified", "basic", "intermediate", "advanced", "expert"])
              .optional()
              .describe(
                "* `unspecified` - Unspecified\n* `basic` - Basic\n* `intermediate` - Intermediate\n* `advanced` - Advanced\n* `expert` - Expert",
              ),
            occupation: zod.uuid().nullish(),
            min_years: zod
              .int()
              .min(organizationsJobsActionResponseRequirementsItemMinYearsMin)
              .max(organizationsJobsActionResponseRequirementsItemMinYearsMax)
              .nullish(),
            language_code: zod
              .string()
              .max(organizationsJobsActionResponseRequirementsItemLanguageCodeMax)
              .optional(),
            language_level: zod
              .enum(["unspecified", "A1", "A2", "B1", "B2", "C1", "C2", "native"])
              .optional()
              .describe(
                "* `unspecified` - Unspecified\n* `A1` - A1\n* `A2` - A2\n* `B1` - B1\n* `B2` - B2\n* `C1` - C1\n* `C2` - C2\n* `native` - Native",
              ),
            education_level: zod
              .enum([
                "none",
                "primary",
                "secondary",
                "baccalaureate",
                "vocational",
                "bac_plus_2",
                "bac_plus_3",
                "bac_plus_5",
                "doctorate",
              ])
              .optional()
              .describe(
                "* `none` - None\n* `primary` - Primary\n* `secondary` - Secondary\n* `baccalaureate` - Baccalaureate\n* `vocational` - Vocational\n* `bac_plus_2` - Bac Plus 2\n* `bac_plus_3` - Bac Plus 3\n* `bac_plus_5` - Bac Plus 5\n* `doctorate` - Doctorate",
              ),
            certification_name: zod
              .string()
              .max(organizationsJobsActionResponseRequirementsItemCertificationNameMax)
              .optional(),
            description: zod
              .string()
              .max(organizationsJobsActionResponseRequirementsItemDescriptionMax)
              .optional(),
          })
          .describe(
            "Rejects unknown input keys (protection against mass assignment and silent typos).",
          ),
      )
      .optional(),
    status: zod
      .enum([
        "draft",
        "submitted",
        "published",
        "paused",
        "closed",
        "expired",
        "rejected",
        "archived",
      ])
      .describe(
        "* `draft` - Draft\n* `submitted` - Submitted\n* `published` - Published\n* `paused` - Paused\n* `closed` - Closed\n* `expired` - Expired\n* `rejected` - Rejected\n* `archived` - Archived",
      ),
    review_status: zod
      .enum([
        "not_submitted",
        "pending",
        "approved",
        "auto_cleared",
        "changes_requested",
        "rejected",
      ])
      .describe(
        "* `not_submitted` - Not Submitted\n* `pending` - Pending\n* `approved` - Approved\n* `auto_cleared` - Auto Cleared\n* `changes_requested` - Changes Requested\n* `rejected` - Rejected",
      ),
    risk_flags: zod.unknown(),
    moderation_hold: zod.boolean(),
    moderation_reason: zod.string(),
    submitted_at: zod.iso.datetime({ offset: true }).nullable(),
    published_at: zod.iso.datetime({ offset: true }).nullable(),
    closed_at: zod.iso.datetime({ offset: true }).nullable(),
    revision: zod.int(),
    created_at: zod.iso.datetime({ offset: true }),
    updated_at: zod.iso.datetime({ offset: true }),
    allowed_actions: zod.array(zod.string()),
  })
  .describe("Rejects unknown input keys (protection against mass assignment and silent typos).");

export const OrganizationsJobsRevisionsListParams = zod.object({
  job_id: zod.uuid(),
  org_id: zod.uuid(),
});

export const OrganizationsJobsRevisionsListResponse = zod.object({
  count: zod.int(),
  next: zod.url().nullable(),
  previous: zod.url().nullable(),
  results: zod.array(
    zod.object({
      revision: zod.int(),
      event: zod.string(),
      changed_fields: zod.unknown(),
      previous_values: zod.unknown(),
      status_from: zod.string(),
      status_to: zod.string(),
      actor: zod.uuid().nullable(),
      created_at: zod.iso.datetime({ offset: true }),
    }),
  ),
});
